#!/usr/bin/env bash
# Runs a program in ORBIT Optimize mode with the settings generated by orbit-analyze.sh.
#
# Usage: orbit-optimize.sh [options] -- <executable> [args...]
#   -c, --conf FILE        best_per_region.json to apply (default: ./orbit_<executable name>/best_per_region.json)
#   -p, --policy POLICY    edp (default), fastest, or both (one run each)
#   -t, --threshold T      ORBIT_TIME_THRESHOLD: minimum region time to be tuned, e.g. 50ms, 0 = every region
#   --baseline             also run the program once without ORBIT, to compare wall-clock times
#   -h, --help
# ORBIT_LIB overrides the liborbit.so path. The program's own output is passed through unchanged; the
# wall-clock time of every run is printed at the end.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ORBIT_LIB="${ORBIT_LIB:-$HERE/../bin/Release/liborbit.so}"
CONF=""
POLICY="edp"
THRESHOLD=""
BASELINE=0

usage() { sed -n '2,/^set -euo/p' "${BASH_SOURCE[0]}" | sed '$d' | sed 's/^# \{0,1\}//'; }
die() { echo "orbit-optimize: $*" >&2; exit 1; }

while [[ $# -gt 0 ]]; do
    case "$1" in
        -c|--conf) CONF="${2:?missing value for $1}"; shift 2 ;;
        -p|--policy) POLICY="${2:?missing value for $1}"; shift 2 ;;
        -t|--threshold) THRESHOLD="${2:?missing value for $1}"; shift 2 ;;
        --baseline) BASELINE=1; shift ;;
        -h|--help) usage; exit 0 ;;
        --) shift; break ;;
        -*) die "unknown option $1 (see --help)" ;;
        *) break ;;
    esac
done

[[ $# -ge 1 ]] || { usage >&2; exit 1; }
case "$POLICY" in edp|best_edp) POLICY=edp ;; fastest|both) ;; *) die "policy must be edp, fastest or both" ;; esac

[[ -f "$ORBIT_LIB" ]] || die "liborbit.so not found at $ORBIT_LIB (build it or set ORBIT_LIB)"
ORBIT_LIB="$(realpath -- "$ORBIT_LIB")"

TARGET="$1"
if [[ "$TARGET" == */* ]]; then
    [[ -x "$TARGET" ]] || die "executable not found or not executable: $TARGET"
else
    TARGET="$(command -v -- "$TARGET")" || die "executable not found in PATH: $1"
fi
TARGET="$(realpath -- "$TARGET")"
shift

CONF="${CONF:-$PWD/orbit_$(basename -- "$TARGET")/best_per_region.json}"
# ORBIT silently falls back to Snapshot mode when the file is missing, so check it here.
[[ -f "$CONF" ]] || die "settings file not found: $CONF (run orbit-analyze.sh first or pass -c)"
CONF="$(realpath -- "$CONF")"

declare -a LABELS=() TIMES=()
run() { # label, then the environment assignments and command to run
    local label="$1" start end
    shift
    echo "[orbit-optimize] $label"
    start="$(date +%s.%N)"
    "$@"
    end="$(date +%s.%N)"
    LABELS+=("$label")
    TIMES+=("$(awk -v s="$start" -v e="$end" 'BEGIN { printf "%.3f", e - s }')")
}

if [[ "$BASELINE" -eq 1 ]]; then
    run "baseline (no ORBIT)" env -u ORBIT_OPTIMIZED_CONF "$TARGET" "$@"
fi

ENV_ARGS=(ORBIT_OPTIMIZED_CONF="$CONF" LD_PRELOAD="$ORBIT_LIB${LD_PRELOAD:+:$LD_PRELOAD}")
[[ -z "$THRESHOLD" ]] || ENV_ARGS+=(ORBIT_TIME_THRESHOLD="$THRESHOLD")

policies=("$POLICY")
[[ "$POLICY" != both ]] || policies=(edp fastest)
for p in "${policies[@]}"; do
    run "optimized, policy=$p" env "${ENV_ARGS[@]}" ORBIT_OPTIMIZE_POLICY="$p" "$TARGET" "$@"
done

echo
echo "[orbit-optimize] wall-clock time (includes input loading):"
for i in "${!LABELS[@]}"; do
    printf '  %-28s %s s\n' "${LABELS[$i]}" "${TIMES[$i]}"
done
